126	    public String getFullTypeName() {
127	        return DBUtils.getFullTypeName(this);
128	    }
129	
130	    @Override
131	    public void setTypeName(@NotNull String typeName) throws DBException
132	    {
133	        this.typeName = typeName;
134	    }
135	
136	    @Override
137	    public void setFullTypeName(@NotNull String fullTypeName) throws DBException {
138	        String plainTypeName;
139	        int divPos = fullTypeName.indexOf("(");
140	        if (divPos == -1) {
141	            plainTypeName = fullTypeName;
142	            validateTypeName(plainTypeName);
143	        } else {
144	            plainTypeName = fullTypeName.substring(0, divPos);
145	            validateTypeName(plainTypeName);
146	            int divPos2 = fullTypeName.indexOf(')', divPos);
147	            if (divPos2 != -1) {
148	                String modifiers = fullTypeName.substring(divPos + 1, divPos2);
149	                int divPos3 = modifiers.indexOf(',');
150	                if (divPos3 == -1) {
151	                    maxLength = precision = CommonUtils.toInt(modifiers, -1);
152	                } else {
153	                    precision= CommonUtils.toInt(modifiers.substring(0, divPos3).trim());
154	                    scale = CommonUtils.toInt(modifiers.substring(divPos3 + 1).trim());
155	                }
156	            }
157	        }
158	        setTypeName(plainTypeName);
159	    }
160	
161	    protected void validateTypeName(String typeName) throws DBException {
162	
163	    }
164	
165	    @Override
166	    public int getTypeID()
167	    {
168	        return valueType;
169	    }
170	
171	    public void setValueType(int valueType)
172	    {
173	        this.valueType = valueType;
174	    }
175	
