53	    private static final List<JexlUberspect.PropertyResolver> POJO = List.of(
54	        JexlUberspect.JexlResolver.PROPERTY,
55	        JexlUberspect.JexlResolver.MAP,
56	        JexlUberspect.JexlResolver.LIST,
57	        JexlUberspect.JexlResolver.DUCK,
58	        JexlUberspect.JexlResolver.FIELD,
59	        JexlUberspect.JexlResolver.CONTAINER);
60	
61	    private static final JexlUberspect.ResolverStrategy JEXL_STRATEGY = (op, obj) -> {
62	        if (op == JexlOperator.ARRAY_GET) {
63	            return JexlUberspect.MAP;
64	        }
65	        if (op == JexlOperator.ARRAY_SET) {
66	            return JexlUberspect.MAP;
67	        }
68	        if (op == null && obj instanceof Map) {
69	            return JexlUberspect.MAP;
70	        }
71	        return POJO;
72	    };
