74	    @NotNull
75	    public static JexlExpression parseExpression(@NotNull String exprString) throws DBException {
76	        synchronized (AbstractDescriptor.class) {
77	            if (jexlEngine == null) {
78	                jexlEngine = new JexlBuilder()
79	                    .cache(100)
80	                    .strategy(JEXL_STRATEGY)
81	                    .create();
82	            }
83	        }
84	        try {
85	            return jexlEngine.createExpression(exprString);
86	        } catch (JexlException e) {
87	            throw new DBException("Bad expression", e);
88	        }
89	    }
