92	    public static JexlContext makeContext(@Nullable Object object, @Nullable Object context) {
93	        return new JexlContext() {
94	            @Override
95	            public Object get(String name) {
96	                return name.equals(VAR_OBJECT) ? object :
97	                    (name.equals(VAR_CONTEXT) ? context : null); //$NON-NLS-1$
98	            }
99	
100	            @Override
101	            public void set(String name, Object value) {
102	                log.warn("Set is not implemented"); //$NON-NLS-1$
103	            }
104	
105	            @Override
106	            public boolean has(String name) {
107	                return name.equals(VAR_OBJECT) && object != null ||
108	                    name.equals(VAR_CONTEXT) && context != null;
109	            }
110	        };
111	    }
