114	    public static Object evalExpression(@NotNull String exprString, @Nullable Object object, @Nullable Object context) {
115	        try {
116	            JexlExpression expression = AbstractDescriptor.parseExpression(exprString);
117	            return expression.evaluate(AbstractDescriptor.makeContext(object, context));
118	        } catch (DBException e) {
119	            log.error("Bad expression: " + exprString, e);
120	            return null;
121	        }
122	    }
