145	        public ObjectType(@NotNull IConfigurationElement cfg, @NotNull String typeAttr) {
146	            this.implName = cfg.getAttribute(typeAttr);
147	            String condition = cfg.getAttribute(ATTR_IF);
148	            if (!CommonUtils.isEmpty(condition)) {
