150	                    this.expression = parseExpression(condition);
151	                } catch (DBException ex) {
152	                    log.warn("Can't parse object type expression: " + condition, ex); //$NON-NLS-1$
153	                }
154	            }
155	            String fcAttr = cfg.getAttribute(ATTR_FORCE_CHECK);
156	            if (!CommonUtils.isEmpty(fcAttr)) {
