198	        public <T> void checkObjectClass(@NotNull Class<T> type) throws DBException {
199	            Class<? extends T> objectClass = getObjectClass(type);
200	            if (implName == null) {
201	                throw new DBException("Implementation class not specified");
202	            }
203	            if (objectClass == null) {
204	                throw new DBException("Class '" + implName + "' not found");
205	            }
206	            if (!type.isAssignableFrom(objectClass)) {
207	                throw new DBException("Class '" + implName + "' do not implements '" + type.getName() + "'");
208	            }
209	        }
