211	        public boolean appliesTo(@NotNull Object object, @Nullable Object context) {
212	            if (!matchesType(object.getClass())) {
213	                return false;
214	            }
215	            if (expression != null) {
216	                try {
217	                    Object result = expression.evaluate(makeContext(object, context));
218	                    return Boolean.TRUE.equals(result);
219	                } catch (Exception e) {
220	                    log.debug("Error evaluating EL expression '" + expression + "'", e);
221	                    return false;
222	                }
223	            }
224	            return true;
225	        }
