227	        @NotNull
228	        public <T> T createInstance(@NotNull Class<T> type, @NotNull Object... args) throws DBException {
229	            if (implName == null) {
230	                throw new DBException("No implementation class name set for '" + type.getName() + "'");
231	            }
232	            Class<? extends T> objectClass = getObjectClass(type);
233	            if (objectClass == null) {
234	                throw new DBException("Can't load class '" + getImplName() + "'");
235	            }
236	            try {
237	                for (Constructor<?> c : objectClass.getConstructors()) {
238	                    Class<?>[] parameterTypes = c.getParameterTypes();
239	                    if (parameterTypes.length == args.length) {
240	                        boolean matches = true;
241	                        for (int i = 0; i < parameterTypes.length; i++) {
242	                            if (!parameterTypes[i].isInstance(args[i])) {
243	                                matches = false;
244	                                break;
245	                            }
246	                        }
247	                        if (matches) {
248	                            return (T) c.newInstance(args);
249	                        }
250	                    }
251	                }
252	
253	                throw new DBException("Cannot find constructor matching args " + Arrays.toString(args));
254	            } catch (Exception e) {
255	                throw new DBException("Can't instantiate class '" + getImplName() + "'", e);
256	            }
257	        }
258	
259	        @NotNull
260	        public <T> T createInstance(@NotNull Class<T> type) throws DBException {
261	            Class<? extends T> objectClass = getObjectClass(type);
262	            if (objectClass == null) {
263	                throw new DBException("Can't load class '" + getImplName() + "'");
264	            }
265	            try {
266	                return objectClass.getDeclaredConstructor().newInstance();
267	            } catch (InstantiationException | IllegalAccessException | NoSuchMethodException |
268	                     InvocationTargetException e) {
269	                throw new DBException("Can't instantiate class '" + getImplName() + "'", e);
270	            }
271	        }
272	
273	        public boolean matchesType(@NotNull Class<?> clazz) {
274	            // Check class only if bundle was loaded or forceCheck is set. Otherwise we'll load ALL bundles which have some
275	            // data type mappings (no matter which type they refer)
276	
277	            if (getContributorBundle().getState() != Bundle.ACTIVE && !forceCheck) {
278	                // Use only type name
279	                return getTypeInfoCache(clazz).containsKey(implName);
280	            }
281	            getObjectClass();
282	            return implClass != null && implClass.isAssignableFrom(clazz);
283	        }
284	
285	        @Override
286	        public String toString() {
287	            return implName;
288	        }
289	    }
