291	    @NotNull
292	    private static synchronized Map<String, Boolean> getTypeInfoCache(@NotNull Class<?> clazz) {
293	        Map<String, Boolean> intCache = classInfoCache.get(clazz.getName());
294	        if (intCache != null) {
295	            return intCache;
296	        }
297	        intCache = new HashMap<>();
298	        classInfoCache.put(clazz.getName(), intCache);
299	        for (Class<?> sc = clazz; sc != null && sc != Object.class; sc = sc.getSuperclass()) {
300	            collectInterface(sc, intCache);
301	        }
302	
303	        return intCache;
304	    }
305	
306	    private static void collectInterface(@NotNull Class<?> clazz, @NotNull Map<String, Boolean> intCache) {
307	        intCache.put(clazz.getName(), Boolean.TRUE);
308	        for (Class<?> i : clazz.getInterfaces()) {
309	            collectInterface(i, intCache);
310	        }
311	    }
