318	    @Nullable
319	    protected static Expression getEnablementExpression(@NotNull IConfigurationElement config, @NotNull String expressionElementName) {
320	        IConfigurationElement[] elements = config.getChildren(expressionElementName);
321	        if (elements.length > 0) {
322	            try {
323	                IConfigurationElement[] enablement = elements[0].getChildren();
324	                if (enablement.length > 0) {
325	                    return ExpressionConverter.getDefault().perform(enablement[0]);
326	                }
327	            } catch (Exception e) {
328	                log.debug(e);
329	            }
330	        }
331	        return null;
332	    }
