334	    protected static boolean isExpressionTrue(@Nullable Expression expression, @Nullable Object exprContext) {
335	        if (expression != null) {
336	            try {
337	                IEvaluationContext context = new EvaluationContext(null, exprContext);
338	                EvaluationResult result = expression.evaluate(context);
339	                if (result != EvaluationResult.TRUE) {
340	                    return false;
341	                }
342	            } catch (CoreException e) {
343	                log.debug(e);
344	                return false;
345	            }
346	        }
347	        return true;
348	    }
