393	    @Nullable
394	    public DBPImage iconToImage(@Nullable String icon) {
395	        if (CommonUtils.isEmpty(icon)) {
396	            return null;
397	        } else if (icon.startsWith("#")) {
398	            // Predefined image
399	            return DBIcon.getImageById(icon.substring(1));
400	        } else {
401	            if (!icon.startsWith("platform:")) {
402	                icon = "platform:/plugin/" + pluginId + "/" + icon;
403	            }
404	            return new DBIcon(icon);
405	        }
406	    }
